<?php
declare(strict_types=1);
require __DIR__.'/test_lucktest_recorder_sql.php';
use Berserk\Core\{Command,Engine,GameRepository,StaleStateException,DbQueryException,LuckTestDice,Dice,Result};
use Berserk\Lobby\{RoomSetup,RoomTransaction,MatchCreator};
$debugSqlStart=$checks;
$config=__DIR__.'/../config/auth.local.php';if(is_file($config))throw new RuntimeException('Refuse to overwrite auth config');
function sqlDebugConfig(array $ids):void{global $config;file_put_contents($config,'<?php return '.var_export(['debug_account_ids'=>$ids],true).';');if(function_exists('opcache_invalidate'))opcache_invalidate($config,true);}
register_shutdown_function(static function()use($config){if(is_file($config))unlink($config);});sqlDebugConfig([11,22]);
function debugSeed($db):\Berserk\Core\GameState{$s=seed($db);$s->settings->lucktest['card_count']=3;$engine=new Engine($db);$r=$engine->apply($s,'host',new Command('set_lucktest_debug',['debug_roll'=>'6,1,4,5','lucktest_scenario'=>json_encode(['cards'=>[['owner'=>'host','ukid'=>'army','row'=>2,'col'=>3]]])]));verify($r->success,'private setup command');(new GameRepository($db))->save($s);return (new GameRepository($db))->findById($s->gameId);}
$s=debugSeed($db);$repo=recording($db,$s->gameId);$stale=$repo->findById($s->gameId);$entry=register($j,$s,'debug-start');
runQuick($repo,$db,$j,$s,(int)$entry['id']);$saved=$repo->findById($s->gameId);$binding=$saved->lucktestDebug['bindings'][0];$pinned=$saved->getCard($binding['instance_id']);
verify($pinned->row===2 && $pinned->col===3 && $saved->lucktestDebug['rolls']['11']['state']['queue']===[4,5],'scenario and cursor durably committed');verify(initialCount($db,$s->gameId)===1,'one initial for scenario');
$entry=register($j,$stale,'debug-stale');$durable=$saved->persistenceJson;try{runQuick($repo,$db,$j,$stale,(int)$entry['id']);verify(false,'stale debug accepted');}catch(StaleStateException){verify($repo->findById($s->gameId)->persistenceJson===$durable,'CAS loser leaves durable cursor untouched');}
foreach($db->fetchAll('SELECT public_json,host_json,player_json FROM battle_history_steps WHERE game_id='.$saved->gameId) as $row)foreach($row as $projection)verify(!str_contains($projection,'lucktest_debug') && !str_contains($projection,'scenario_account_id') && !str_contains($projection,'debug_roll'),'history does not publish private scenario/queue');
// Rejection after consuming a native die cannot advance the persisted cursor.
$cmd=new Command('end_turn');$entry=$j->registerProcessing($saved->gameId,'host','debug-rejected','end_turn',[],$saved->persistenceVersion);
$repo->executeLockedCommand($saved,$j,(int)$entry['id'],fn($locked)=>LuckTestDice::run($locked,'host',static function(){Dice::roll();return Result::error('test rejection');}));
verify($repo->findById($saved->gameId)->persistenceJson===$durable && $j->findById((int)$entry['id'])['status']==='rejected','rejected journal preserves durable queue');
foreach(['game','history'] as $fault){$s=debugSeed($db);$repo=recording($db,$s->gameId);$entry=register($j,$s,'debug-'.$fault.'-failure');$before=$s->persistenceJson;$table=$fault==='game'?'games':'battle_history_steps';
$raw->query("CREATE TRIGGER debug_fault BEFORE ".($fault==='game'?'UPDATE':'INSERT')." ON $table FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='debug atomicity fixture'");
try{runQuick($repo,$db,$j,$s,(int)$entry['id']);verify(false,'injected debug SQL failure accepted');}catch(DbQueryException){$loaded=$repo->findById($s->gameId);verify($loaded->persistenceJson===$before && $loaded->status==='settings','SQL failure retains scenario and unconsumed cursor');verify(initialCount($db,$s->gameId)===0 && $j->findById((int)$entry['id'])['status']==='processing','SQL failure leaves no partial initial or committed journal');}finally{$raw->query('DROP TRIGGER debug_fault');}
runQuick($repo,$db,$j,$s,(int)$entry['id']);verify($repo->findById($s->gameId)->lucktestDebug['rolls']['11']['state']['queue']===[4,5] && initialCount($db,$s->gameId)===1,'retry consumes once');}
// Actual Lobby owner transaction, including revocation at acceptance and failed append.
$historyConfig=__DIR__.'/../config/battle_history.local.php';if(is_file($historyConfig))throw new RuntimeException('Refuse to overwrite history config');
try{foreach(['success','revoked','history_failure'] as $scenario){sqlDebugConfig([11,22]);$setup=RoomSetup::parse('lucktest',['lucktest_card_count'=>'3','lucktest_scenario'=>json_encode(['cards'=>[['owner'=>'host','ukid'=>'army','row'=>2,'col'=>3]]]),'debug_roll'=>'6,1,4'],11);$json=$raw->real_escape_string(json_encode($setup));$token=str_repeat('c',64);$raw->query("INSERT INTO lobby_rooms(creator_account_id,candidate_account_id,candidate_request_id,state,created_at,updated_at,game_type,setup_json) VALUES(11,22,'$token','awaiting_confirmation',UTC_TIMESTAMP(6),UTC_TIMESTAMP(6),'lucktest','$json')");$room=(int)$raw->insert_id;$next=(int)$db->fetchOne("SELECT AUTO_INCREMENT n FROM information_schema.TABLES WHERE TABLE_SCHEMA='$schema' AND TABLE_NAME='games'")['n'];file_put_contents($historyConfig,'<?php return '.var_export(['recording_enabled'=>true,'record_game_ids'=>[$next],'catalog'=>$catalog],true).';');
if($scenario==='revoked')sqlDebugConfig([]);if($scenario==='history_failure')$raw->query("CREATE TRIGGER debug_fault BEFORE INSERT ON battle_history_steps FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='lobby debug failure'");
try{RoomTransaction::run($raw,function($tx)use($room,$raw,&$id){$id=MatchCreator::create($tx,$room,11,22);$raw->query("UPDATE lobby_rooms SET state='started',candidate_account_id=NULL,candidate_request_id=NULL,accepted_account_id=22,game_id=$id WHERE id=$room");});verify($scenario==='success','unexpected Lobby debug commit');$loaded=(new GameRepository($db))->findById($id);verify($loaded->status==='battle' && $loaded->lucktestDebug['rolls']['11']['state']['queue']===[4] && initialCount($db,$id)===1,'Lobby commits required cell/cursor/initial together');}
catch(Throwable $e){if($scenario==='success')throw $e;verify($scenario==='revoked'?$e instanceof DomainException:$e instanceof DbQueryException,'expected Lobby debug error');verify($db->fetchOne("SELECT * FROM games WHERE ind=$next")===null && initialCount($db,$next)===0,'Lobby rejection/rollback leaves no game or history');verify($db->fetchOne("SELECT state FROM lobby_rooms WHERE id=$room")['state']==='awaiting_confirmation','room remains pending');}
finally{if($scenario==='history_failure')$raw->query('DROP TRIGGER debug_fault');}}
}finally{unlink($historyConfig);unlink($config);}
echo 'LuckTest Debug SQL: '.($checks-$debugSqlStart)." checks passed (isolated MariaDB).\n";
